sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    let avatars = api.state.authorObject;
    if (event.elementId == 'save_button') {
        const addCoAuthors = api.data.save_co_authors_for_post_incident_report;
        addCoAuthors.execute({
            sysId: api.context.props.sysId,
            coAuthors: avatars
        });
        api.setState('disableSave', true);
    } else if (event.elementId == 'fetch_incident_related_data') {
        if (avatars.length > 5) {
            let req = avatars.length - 5;
            api.setState('additionalAvatarCount', "+" + req);
            api.setState('visibleAvatars', avatars.slice(0, 5));
            api.setState('hideLink', false);
        } else {
            api.setState('visibleAvatars', avatars);
            api.setState('hideLink', true);
        }
    } else {
        api.setState('visibleAvatars', avatars);
        api.setState('hideLink', true);
    }

}
